'use strict';
// THE VISUAL DIRECTOR, ON REAL PHOTOGRAPHS: the six subjects of test/helpers/creative-subjects.js rebuilt from real,
// freely licensed photos (kept outside the repository), measured by the studio's own code (assets.js assess / cutout, run
// in the capture browser), each page generated by the current pipeline, then reviewed by the visual director -- before
// and after at 1440 and 390, scene by scene.
//   node test/review/creative-visual-review.js <photoDir> <outDir>
// photoDir holds <id>.jpg|png for the picture ids below, measured.json (from the studio's measuring) and, optionally,
// subjects.json ({ id: [x0, y0, x1, y1] } -- where the subject is in a busy photo, as the studio's curation would say).
// The model is a mock that answers with what was MEASURED (the serious problems, the worst first, each with the first
// repair offered): it cannot see. Nothing here calls a paid provider.
const fs = require('fs');
const path = require('path');
const D2 = require('../../lib/creative/director2');
const DIR = require('../../lib/creative/direction');
const AI = require('../../lib/creative/ai');
const VC = require('../../lib/creative/visual-capture');
const VR = require('../../lib/creative/visual-review');
const { validatePlan2 } = require('../../lib/creative/validate2');
const { SUBJECTS, IDS } = require('../helpers/creative-subjects');
const { svgOf } = require('../helpers/stand-in-pictures');

const [photoDir, outDir] = [path.resolve(process.argv[2] || 'photos'), path.resolve(process.argv[3] || 'visual-review')];
const measured = JSON.parse(fs.readFileSync(path.join(photoDir, 'measured.json'), 'utf8'));
const boxes = fs.existsSync(path.join(photoDir, 'subjects.json')) ? JSON.parse(fs.readFileSync(path.join(photoDir, 'subjects.json'), 'utf8')) : {};
const fileOf = id => ['jpg', 'png'].map(e => path.join(photoDir, `${id}.${e}`)).find(f => fs.existsSync(f));

// a subject's pictures as the studio would hold them: the real photo, its measurement, its cut-out only if one was clean
function real(id) {
  const s = SUBJECTS[id]; const assets = [];
  s.assets.forEach(a => {
    if (a.cutout) { const of = a.cutoutOf; const m = measured[of] && measured[of].cut && measured[of].cut.assess; if (!m || !fs.existsSync(path.join(photoDir, `c-${of}.png`))) return; assets.push(Object.assign({}, a, { mime: 'image/png', assess: m, file: path.join(photoDir, `c-${of}.png`) })); return; }
    const f = fileOf(a.id); if (!f || !measured[a.id]) { assets.push(Object.assign({}, a, { stand: true })); return; } // (the invented logos stay drawn)
    const m = Object.assign({}, measured[a.id].assess); if (boxes[a.id]) m.subject = boxes[a.id];
    assets.push(Object.assign({}, a, { mime: /png$/.test(f) ? 'image/png' : 'image/jpeg', assess: m, file: f }));
  });
  return Object.assign({}, s, { assets });
}
const pictures = a => (a.file ? { buf: fs.readFileSync(a.file), mime: a.mime } : { buf: Buffer.from(svgOf(a)), mime: 'image/svg+xml' });
const shape = sc => sc.composition || sc.layout;
const RANK = ['hero_subject_too_small', 'weak_final_payoff', 'competing_heading_overlap', 'looks_unfinished', 'headline_lost_in_image', 'mobile_loses_impact', 'hero_lacks_dominance', 'payoff_weaker_than_previous'];
const rank = (a, b) => ((b.severity === 'high') - (a.severity === 'high')) || ((RANK.includes(a.issue) ? RANK.indexOf(a.issue) : 99) - (RANK.includes(b.issue) ? RANK.indexOf(b.issue) : 99));

(async () => {
  fs.mkdirSync(outDir, { recursive: true }); const br = await VC.launch(VC.findBrowser({ CREATIVE_VISUAL_BROWSER: process.env.CREATIVE_VISUAL_BROWSER || 'auto' }));
  const report = [];
  try {
    for (const id of (process.argv[4] ? process.argv[4].split(',') : IDS)) {
      const s = real(id); const seed = '1';
      const { plan, recipe } = D2.direct({ understanding: s.understanding, research: { page: null, facts: s.facts }, assets: s.assets, supplied: { facts: [], memories: [] }, seed, mainAsset: s.mainAsset });
      const v = validatePlan2(plan, { assets: s.assets, facts: s.facts, understanding: s.understanding, art: recipe, mainAsset: s.mainAsset });
      if (v.errors.length) throw new Error(`${id}: ${v.errors[0]}`);
      const input = { assets: s.assets, facts: s.facts, understandingLegacy: s.understanding, mainAsset: s.mainAsset };
      const call = async q => { const t = q.content.find(c => c.type === 'text' && c.text.startsWith('What was measured')).text; const h = JSON.parse(t.slice(t.indexOf('{')));
        return { model: 'mock-measured', usage: { input_tokens: 3400, output_tokens: 160 }, input: { verdict: h.measured.length ? 'almost' : 'strong', issues: h.measured.filter(m => m.offered.length && m.severity !== 'low').sort(rank).slice(0, 6).map(m => ({ scene: m.scene, view: m.view, issue: m.issue, severity: m.severity, repair: m.offered[0] })) } }; };
      const out = await AI.visualReview(v.plan, input, { limits: Object.assign(AI.limits({}), { visual: true }), call, liveBrowser: br, pictures });
      // before / after, every scene, at both widths
      const b = await VR.look(v.plan, input, { pictures }, br); const a = await VR.look(out.plan, input, { pictures }, br);
      const tiles = []; v.plan.scenes.forEach((sc, i) => { tiles.push({ png: b.shots.desktop[i], label: `${id} BEFORE ${i} ${shape(sc)}` }); tiles.push({ png: a.shots.desktop[i], label: `${id} AFTER ${i} ${shape(out.plan.scenes[i])}${out.meta.kept.some(k => k.scene === sc.id) ? '  << repaired' : ''}` }); });
      fs.writeFileSync(path.join(outDir, `${id}-desktop.jpg`), await VC.sheet(br, tiles, { cols: 2, w: 640, h: 400, quality: 78 }));
      const mt = []; v.plan.scenes.forEach((sc, i) => { mt.push({ png: b.shots.mobile[i], label: `B${i}` }); mt.push({ png: a.shots.mobile[i], label: `A${i}${out.meta.kept.some(k => k.scene === sc.id) ? '*' : ''}` }); });
      fs.writeFileSync(path.join(outDir, `${id}-mobile.jpg`), await VC.sheet(br, mt, { cols: 10, w: 156, h: 338, quality: 78 }));
      const ctx = p => AI.reviewContext(p, new Map(s.assets.map(x => [x.id, x])), input);
      const row = { id, genre: v.plan.idea.concept.genre, intensity: v.plan.idea.concept.intensity, sequence: v.plan.scenes.map(shape).join(' > '), after: out.plan.scenes.map(shape).join(' > '),
        structural: { before: DIR.score(DIR.critique(v.plan.scenes, ctx(v.plan))), after: DIR.score(DIR.critique(out.plan.scenes, ctx(out.plan))) }, visual: { before: out.plan.visualReview && out.plan.visualReview.before, after: out.plan.visualReview && out.plan.visualReview.after },
        found: out.meta.found, kept: out.meta.kept, reverted: out.meta.reverted, ms: out.meta.ms, captureMs: out.meta.captureMs, imageBytes: out.meta.imageBytes, attempts: out.meta.attempts };
      report.push(row); fs.writeFileSync(path.join(outDir, `${id}.plans.json`), JSON.stringify({ before: v.plan, after: out.plan }));
      process.stdout.write(`${id} (${row.genre}/${row.intensity}) visual ${row.visual.before}->${row.visual.after} structural ${row.structural.before}->${row.structural.after} ${row.ms}ms\n   ${row.sequence}\n`);
      out.meta.found.filter(f => f.severity !== 'low').forEach(f => process.stdout.write(`   found  ${f.scene} ${f.issue} (${f.view}, ${f.severity})\n`));
      out.meta.kept.forEach(k => process.stdout.write(`   KEPT   ${k.scene} ${k.issue} -> ${k.repair} (${k.view})\n`)); out.meta.reverted.forEach(k => process.stdout.write(`   undone ${k.scene} ${k.issue} -> ${k.repair}: ${k.why}\n`));
    }
  } finally { await br.close(); fs.writeFileSync(path.join(outDir, 'visual-report.json'), JSON.stringify(report, null, 1)); }
})().catch(e => { console.error(e.stack); process.exit(1); });
